acing:.13em;color:#aeb4be}.menu-top{top:5.7%}.edition b{color:var(--red);font-weight:500}.menu-date{color:#7d8798}.menu-copy{position:absolute;left:9.2%;top:20%;width:min(35%,460px)}.eyebrow{font:10px var(--mono);letter-spacing:.2em;color:var(--red);margin:0 0 15px}.menu-copy h1{font:800 clamp(44px,6.7vw,87px)/.83 var(--display);letter-spacing:-.025em;text-transform:uppercase;margin:0;text-shadow:0 4px 30px #03050b}.menu-copy h1 em{font-weight:500;color:#d4d7de}.subcopy{font:12px var(--mono);letter-spacing:.025em;color:#b1b8c2;margin:17px 0}.main-nav{position:absolute;left:9.2%;top:47%;width:min(365px,39vw);display:flex;flex-direction:column;gap:2px}.main-nav button{height:39px;background:transparent;border:0;border-left:2px solid transparent;display:grid;grid-template-columns:37px 1fr auto;align-items:center;text-align:left;padding:0 12px 0 13px;color:#aab1be;cursor:pointer;transition:.18s ease;font-size:17px;font-weight:600;letter-spacing:.015em}.main-nav button .num{font:10px var(--mono);color:#727d8d}.main-nav button small{font:8px var(--mono);letter-spacing:.09em;color:#6b7482;opacity:0;transition:.18s}.main-nav button:hover,.main-nav button.selected{background:linear-gradient(90deg,rgba(237,40,55,.21),rgba(237,40,55,0));border-left-color:var(--red);color:#fff;padding-left:18px}.main-nav button.selected .num{color:var(--red)}.main-nav button.selected small{opacity:1}.menu-bottom{bottom:4.7%;font-size:8px;color:#697483}.press{display:flex;gap:10px;align-items:center}.press b{color:#c6cbd3;font-weight:400}.press kbd,.dialogue kbd,.pause-actions kbd{font:10px var(--mono);padding:3px 5px;border:1px solid #687281;color:#dbe0e6}.sub-panel{background:linear-gradient(90deg,rgba(7,10,17,.97) 0%,rgba(7,10,17,.92) 58%,rgba(7,10,17,.6));padding:10vh 9vw 7vh;overflow:auto}.back-btn{border:0;background:transparent;color:#adb4c0;font:11px var(--mono);letter-spacing:.12em;cursor:pointer;margin-bottom:32px}.back-btn:hover{color:white}.sub-panel h2{font:800 clamp(43px,6vw,74px)/