er:1px solid #6c7480;margin:0 4px 0 9px}.mini-map{width:127px;height:105px;background:rgba(8,12,20,.76);border:1px solid rgba(255,255,255,.19);padding:8px;position:relative}.map-label{font:7px var(--mono);letter-spacing:.1em;color:#9fa8b5}.map-grid{position:absolute;inset:27px 8px 8px;background:repeating-linear-gradient(90deg,transparent 0 17px,rgba(116,142,163,.22) 17px 20px),repeating-linear-gradient(0deg,transparent 0 15px,rgba(116,142,163,.22) 15px 18px);transform:skewY(-7deg)}.map-player,.map-target{position:absolute;display:block;width:6px;height:6px;background:#fff;left:49%;top:55%;box-shadow:0 0 7px white}.map-target{background:var(--red);left:72%;top:27%;box-shadow:0 0 8px var(--red)}.map-grid b{position:absolute;left:70%;top:25%;font:10px var(--mono);color:var(--red)}.toast{position:absolute;left:50%;top:23%;transform:translate(-50%,-10px);font:10px var(--mono);letter-spacing:.12em;color:white;background:rgba(10,14,23,.9);padding:11px 18px;border:1px solid rgba(255,255,255,.19);opacity:0;transition:.3s}.toast.show{opacity:1;transform:translate(-50%,0)}.interact-prompt{position:absolute;left:50%;top:54%;transform:translate(-50%,-50%);font:10px var(--mono);letter-spacing:.1em;color:white;background:rgba(8,12,20,.78);padding:8px 12px}.interact-prompt kbd{padding:3px 6px;border:1px solid white;margin-right:8px}.overlay-screen{position:absolute;inset:0;z-index:6;background:rgba(3,6,12,.63);backdrop-filter:blur(4px);display:flex;justify-content:flex-end}.pause-card{width:min(440px,52vw);height:100%;background:rgba(9,13,22,.95);border-left:1px solid var(--line);padding:12vh 7% 5%;box-shadow:-30px 0 80px #04060b}.pause-card h2{font:800 65px/.78 var(--display);text-transform:uppercase;margin:0 0 32px}.pause-card h2 em{font-weight:500;color:#abb4c1}.pause-actions{display:grid}.pause-actions button{height:50px;text-align:left;padding:0 12px;border:0;border-bottom:1px solid rgba(255,255,255,.1);background:transparent;font:600 18px var(--display);cursor:pointer;color: