k;width:4px;height:4px;background:var(--red);border-radius:50%;animation:pulse .6s infinite alternate}.load-line{width:200px;height:2px;background:#28303b;margin-top:18px}.load-line i{display:block;height:100%;background:var(--red);width:35%;animation:load 1s ease-in-out infinite alternate}.legal{position:absolute;z-index:2;right:2%;bottom:1.6%;font:7px var(--mono);letter-spacing:.09em;color:rgba(181,189,201,.48)}.mobile-controls{display:none}.mobile-controls button{pointer-events:auto;background:rgba(12,18,29,.68);color:white;border:1px solid rgba(255,255,255,.35);border-radius:50%;width:48px;height:48px;font:12px var(--mono)}.dpad{display:grid;grid-template-columns:repeat(3,48px);gap:4px;align-items:center}.dpad button:nth-child(2){grid-column:2;grid-row:1}.dpad button:first-child{grid-column:1;grid-row:2}.dpad button:last-child{grid-column:3;grid-row:2}.actions{display:grid;grid-template-columns:repeat(2,48px);gap:8px}.actions button{width:44px;height:44px;font-size:9px}.actions button:nth-child(1){background:rgba(70,166,200,.55)}.actions button:nth-child(2){background:rgba(216,42,55,.65)}@keyframes pulse{to{opacity:.15}}@keyframes load{to{width:100%}}@keyframes cardin{from{opacity:0}to{opacity:1}}
