const canvas=document.querySelector('#scene'),ctx=canvas.getContext('2d',{alpha:false}),$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];let W=0,H=0,dpr=1,state='menu',time=0,last=0,keys={},menuIndex=0,chapter=0,missionStep=0,player={x:.49,y:.63,vx:0,vy:0,health:100,focus:0,xp:0,level:1,attack:0,dodge:0,jump:0,web:0},camera={x:0,y:0},weather=[],buildings=[],cityLights=[],enemy=[],collectibles=[],save=JSON.parse(localStorage.getItem('ny-afterdark-save')||'null');
const chapters=[{title:'O ÚLTIMO DIA DE FISK',place:'HELL’S KITCHEN',objectives:['Chegue ao complexo de Fisk','Encontre a entrada do pátio','Derrote os guardas','Desative os bloqueadores','Enfrente Wilson Fisk'],intro:['Toda cidade tem seus monstros. Alguns usam terno caro.','Centro de operações da polícia. Manhattan, 2h17 da manhã.','Uma noite perfeita pra encerrar uma carreira.','Yuri, estou no telhado. Qual é a situação?','Fisk está dentro. Não deixa ele escapar dessa vez, Spider.'],boss:'WILSON FISK',reward:'+ 500 XP · 1 ficha de crime'}, {title:'MÁQUINA DE PRECISÃO',place:'UPPER WEST SIDE',objectives:['Visite o laboratório do Dr. Octavius','Calibre os braços mecânicos','Investigue o apagão no laboratório'],intro:['Peter! Chegou bem na hora. Preciso de uma segunda opinião.','Otto, você está forçando demais os motores.','A ciência nunca espera o momento perfeito, Peter.'],boss:'PROTOCOLO OCTAVIUS',reward:'+ 350 XP · Traje clássico'}, {title:'SOMBRAS DE MANHATTAN',place:'CHINATOWN',objectives:['Investigue os símbolos dos Demônios','Siga o rastro até o cais','Intercepte a carga clandestina'],intro:['Os Demônios deixaram marcas pela cidade inteira.','Yuri, achei um carregamento no cais. Isso não parece contrabando comum.','Tenha cuidado. Martin Li está sempre um passo à frente.'],boss:'ESQUADRÃO DEMÔNIO',reward:'+ 600 XP · 2 fichas de base'}, {title:'RESPIRAR FUNDO',place:'FINANCIAL DISTRICT',objectives:['Proteja o abrigo F.E.A.S.T.','Ajude May a evacuar os civis','Encontre Martin Li'],intro:['May, eu estou chegando. Aguenta só mais um pouco.','Peter, essas pessoas precisam de você. Não de uma máscara.','Eu sei, May. Só preciso fazer isso direito.'],boss:'MARTIN LI',reward:'+ 800 XP · habilidade desbloqueada'}, {title:'A CIDADE EM QUEDA',place:'MIDTOWN',objectives:['Ajude os civis no cruzamento','Destrua os drones de vigilância','Derrote os reforços dos Demônios'],intro:['A cidade toda está em alerta. Nunca vi nada assim.','Spider-Man, temos múltiplas ocorrências!','Então vamos apagar incêndio por incêndio.'],boss:'CAOS EM MANHATTAN',reward:'+ 1.000 XP · 3 fichas de crime'}, {title:'O ÚLTIMO ATO',place:'OSCORP TOWER',objectives:['Suba até o topo da torre Oscorp','Supere Otto na cobertura','Salve a cidade'],intro:['Você sempre tentou consertar tudo, Otto.','E você sempre achou que podia salvar todo mundo!','Não precisa acabar assim.','Acabou no momento em que escolheu a cidade em vez de mim.','Eu não escolhi, Otto. Eu fiz o que era certo.'],boss:'DOUTOR OCTOPUS',reward:'+ 2.000 XP · NOVA YORK SALVA'}];
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=canvas.clientWidth;H=canvas.clientHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);seedCity()}
function rnd(n){let x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)}
function seedCity(){buildings=[];cityLights=[];for(let i=0;i<32;i++){let w=30+rnd(i+5)*70;buildings.push({x:i*W/20-W*.15,w,h:H*(.17+rnd(i+32)*.49),depth:i%3,seed:i+3});}for(let i=0;i<220;i++)cityLights.push({x:rnd(i*3+9)*W,y:rnd(i*11+4)*H*.69,r:1+rnd(i+8)*1.5,a:.18+rnd(i+3)*.65,c:i%5===0?'#ffbf74':'#6dc5e6'});weather=Array.from({length:110},(_,i)=>({x:rnd(i+101)*W,y:rnd(i+8)*H,s:2+rnd(i+12)*5}))}
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.ceil(w),Math.ceil(h))}
function drawSky(){let g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#090e1b');g.addColorStop(.47,'#17192a');g.addColorStop(1,'#232338');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);let moonX=W*.77,moonY=H*.21;ctx.fillStyle='rgba(151,192,226,.06)';ctx.beginPath();ctx.arc(moonX,moonY,88,0,7);ctx.fill();ctx.fillStyle='#b9ccdb';ctx.beginPath();ctx.arc(moonX,moonY,12,0,7);ctx.fill();ctx.fillStyle='#0c1120';ctx.beginPath();ctx.arc(moonX+5,moonY-4,10,0,7);ctx.fill();for(let i=0;i<65;i++){let sx=rnd(i+70)*W,sy=rnd(i+32)*H*.53;rect(sx,sy,1,1,'rgba(210,225,242,.5)')}
  // distant skyline
  for(let layer=0;layer<3;layer++){let base=H*(.74+layer*.05),step=50+layer*19;for(let i=-1;i<Math.ceil(W/step)+2;i++){let x=i*step+((time*.007*(layer+1))%step),w=step*.72,h=H*(.2+rnd(i+layer*46)*.33);rect(x,base-h,w,h,['#111a2a','#111725','#101522'][layer]);if(layer===0){rect(x+w*.48,base-h-18,2,18,'#222c3c');rect(x+w*.48-3,base-h-8,8,2,'#29394a')}for(let yy=base-h+12;yy<base-4;yy+=10)for(let xx=x+6;xx<x+w-4;xx+=9)if(rnd(xx*yy+i)>.52)rect(xx,yy,2,3,`rgba(230,177,106,${.22+rnd(xx+yy)*.4})`)}}
  // city light haze
